// api.ts
export interface User {
  id: number;
  name: string;
}

export const fetchUser = async (id: number): Promise<User> => {
  const response = await fetch(`/api/users/${id}`);
  return response.json();
};

// __tests__/api.test.ts
import { fetchUser, User } from '../api';

// Tell TypeScript this is a mock
jest.mock('../api');

// The mock is typed with the original module's types
const mockFetchUser = fetchUser as jest.MockedFunction<typeof fetchUser>;

mockFetchUser.mockResolvedValue({ id: 1, name: 'Alice' } as User);

// Test uses the typed mock
async function testFetchUser() {
  const user = await mockFetchUser(1);
  expect(user.name).toBe('Alice'); // TypeScript knows user is User
}

interface ButtonProps {
  label: string;
  onClick: () => void;
}

function Button({ label, onClick }: ButtonProps) {
  return <button onClick={onClick}>{label}</button>;
}

// Parent component that uses Button
function Form({ onSubmit }: { onSubmit: () => void }) {
  return (
    <form onSubmit={onSubmit}>
      <Button label="Submit" onClick={onSubmit} />
    </form>
  );
}

// Test with mocked Button
jest.mock('./Button', () => ({
  __esModule: true,
  default: jest.fn(({ label, onClick }: ButtonProps) => (
    <button data-testid="mock-button" onClick={onClick}>{label}</button>
  ))
}));

function FormTest() {
  const handleSubmit = jest.fn();

  render(<Form onSubmit={handleSubmit} />);

  const button = screen.getByTestId('mock-button');
  fireEvent.click(button);
  expect(handleSubmit).toHaveBeenCalled();
}

import { render, RenderOptions } from '@testing-library/react';
import { ThemeProvider } from '../ThemeProvider';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

interface CustomRenderOptions extends Omit<RenderOptions, 'wrapper'> {
  theme?: 'light' | 'dark';
}

function customRender(ui: ReactElement, options?: CustomRenderOptions) {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false } }
  });

  return render(
    <QueryClientProvider client={queryClient}>
      <ThemeProvider theme={options?.theme || 'light'}>
        {ui}
      </ThemeProvider>
    </QueryClientProvider>,
    options
  );
}

export * from '@testing-library/react';
export { customRender as render };
